import java.util.*;
import java.io.*;

public class Main {
    static List<List<Integer>> findEdges(int n, int[][] edges) {
        // Write your solution here
        // Return a list of two lists: critical indices, pseudo-critical indices
        List<List<Integer>> res = new ArrayList<>();
        res.add(new ArrayList<>());
        res.add(new ArrayList<>());
        return res;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        int[][] edges = new int[m][3];
        for (int i = 0; i < m; i++) {
            for (int k = 0; k < 3; k++) {
                in.nextToken();
                edges[i][k] = (int) in.nval;
            }
        }
        List<List<Integer>> res = findEdges(n, edges);
        StringBuilder sb = new StringBuilder();
        for (int k = 0; k < 2; k++) {
            sb.append(res.get(k).size());
            for (int x : res.get(k)) sb.append(' ').append(x);
            sb.append('\n');
        }
        System.out.print(sb);
    }
}
